package main

import (
	"errors"
	"fmt"
)

// div returns the quotient and an error; the (T, error) pair is the Go idiom.
func div(a, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("division by zero") // return a zero value plus the error
	}
	return a / b, nil // nil error signals success
}

func main() {
	q, err := div(10, 2)
	if err != nil { // ALWAYS check the error before trusting the value
		fmt.Println("error:", err)
		return
	}
	fmt.Println("10 / 2 =", q)

	// Trigger the failure path.
	if _, err := div(10, 0); err != nil { // discard the value with _, keep the error
		fmt.Println("error:", err)
	}
}

