import (
	"fmt"
)

// split uses named returns x and y, then a naked `return`.
func split(sum int) (x, y int) {
	x = sum * 4 / 9 // x and y are pre-initialized to 0 and act as locals
	y = sum - x
	return // naked return: hands back the current x and y
}

// parse demonstrates defer reading and MUTATING a named return value.
func parse(s string) (n int, err error) {
	defer func() {
		if err != nil { // the deferred closure sees the named return err
			err = fmt.Errorf("parse %q: %w", s, err) // wrap and reassign it
		}
	}()
	if s == "" {
		return 0, fmt.Errorf("empty input")
	}
	return len(s), nil
}

func main() {
	x, y := split(17)
	fmt.Println("split:", x, y)

	_, err := parse("")
	fmt.Println("err:", err) // shows the wrapped message added by defer
}

package main

import "fmt"

// sum accepts zero or more ints; inside, nums is a []int.
func sum(nums ...int) int {
	total := 0
	for _, n := range nums { // iterate the collected slice
		total += n
	}
	return total
}

func main() {
	fmt.Println(sum(1, 2, 3))   // pass individual args
	fmt.Println(sum())          // zero args -> nums is an empty (nil) slice

	values := []int{4, 5, 6}
	fmt.Println(sum(values...)) // spread the slice with ... (no element copy)
}

package main

import "fmt"

// makeCounter returns a closure that captures and mutates `count`.
func makeCounter() func() int {
	count := 0 // captured by reference, lives on the heap
	return func() int {
		count++ // each call mutates the SAME captured variable
		return count
	}
}

// apply is a higher-order function: it takes a function as an argument.
func apply(vals []int, f func(int) int) []int {
	out := make([]int, len(vals))
	for i, v := range vals {
		out[i] = f(v) // call the passed-in function
	}
	return out
}

func main() {
	next := makeCounter()
	fmt.Println(next(), next(), next()) // 1 2 3 — shared captured state

	doubled := apply([]int{1, 2, 3}, func(x int) int { return x * 2 })
	fmt.Println(doubled)
}
